package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string
var WsTax decimal.Decimal
var WsNet decimal.Decimal
var WsTotalTax decimal.Decimal
var WsCount int64
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var taxFile *os.File
var reader *bufio.Reader

const TaxRecLen = 13

func parseNumericDisplay(raw string, scale int) decimal.Decimal {
	var sb strings.Builder
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if c >= '0' && c <= '9' {
			sb.WriteByte(c)
		} else if c == ' ' {
			sb.WriteByte('0')
		} else {
			sb.WriteByte('0')
		}
	}
	sDigits := sb.String()
	if sDigits == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(sDigits)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(int32(-scale))
	return d
}

func applyOverflow(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if val.IsNegative() {
		abs := val.Abs()
		resAbs := applyOverflow(abs, intDigits, scale)
		return resAbs.Neg()
	}
	intPart := val.Truncate(0)
	pow10 := decimal.New(1, int32(intDigits))
	if intPart.Cmp(pow10) >= 0 {
		rem := intPart.Mod(pow10)
		frac := val.Sub(intPart)
		newVal := rem.Add(frac)
		return newVal
	}
	return val
}

func storeRounded(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	r := val.Round(int32(scale))
	return applyOverflow(r, intDigits, scale)
}

func storeTruncated(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	t := val.Truncate(int32(scale))
	return applyOverflow(t, intDigits, scale)
}

func pictureScale(pic string) int {
	idx := strings.Index(pic, ".")
	if idx == -1 {
		return 0
	}
	cnt := 0
	for _, ch := range pic[idx+1:] {
		if ch == 'Z' || ch == '9' {
			cnt++
		}
	}
	return cnt
}

func pictureIntDigits(pic string) int {
	idx := strings.Index(pic, ".")
	var intPic string
	if idx == -1 {
		intPic = pic
	} else {
		intPic = pic[:idx]
	}
	cnt := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			cnt++
		}
	}
	return cnt
}

func formatEdited(val decimal.Decimal, pic string) string {
	scale := pictureScale(pic)
	intDigits := pictureIntDigits(pic)
	abs := val.Abs()
	// Truncate to picture scale (MOVE without ROUNDED)
	absTrunc := abs.Truncate(int32(scale))
	s := absTrunc.StringFixed(int32(scale))
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		}
	} else {
		intStr = s
		fracStr = ""
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	dotPos := strings.Index(pic, ".")
	intPicEnd := len(pic)
	if dotPos != -1 {
		intPicEnd = dotPos
	}
	res := []byte(pic)
	intIdx := 0
	for i := 0; i < intPicEnd; i++ {
		ch := pic[i]
		if ch == 'Z' || ch == '9' {
			res[i] = intStr[intIdx]
			intIdx++
		} else if ch == ',' {
			res[i] = ','
		} else {
			res[i] = byte(ch)
		}
	}
	if dotPos != -1 {
		res[dotPos] = '.'
		fracIdx := 0
		for i := dotPos + 1; i < len(pic); i++ {
			ch := pic[i]
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracStr) {
					res[i] = fracStr[fracIdx]
					fracIdx++
				} else {
					res[i] = '0'
				}
			} else {
				res[i] = byte(ch)
			}
		}
	}
	suppressed := true
	for i := 0; i < intPicEnd; i++ {
		ch := pic[i]
		if ch == 'Z' {
			if suppressed && res[i] == '0' {
				res[i] = ' '
			} else {
				suppressed = false
			}
		} else if ch == '9' {
			suppressed = false
		} else if ch == ',' {
			if suppressed {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		}
	}
	return string(res)
}

func readPara() {
	if reader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := reader.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			if line == "" {
				WsEofFlag = "Y"
				return
			}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	if strings.HasSuffix(line, "\n") {
		line = line[:len(line)-1]
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
	} else if strings.HasSuffix(line, "\r") {
		line = line[:len(line)-1]
	}
	if len(line) < TaxRecLen {
		line = line + strings.Repeat(" ", TaxRecLen-len(line))
	} else if len(line) > TaxRecLen {
		line = line[:TaxRecLen]
	}
	trId := line[0:5]
	rawIncome := line[5:13]
	trIncome := parseNumericDisplay(rawIncome, 2)
	taxRec = TaxRec{
		TrId:     trId,
		TrIncome: trIncome,
	}
	WsEofFlag = "N"
}

func processPara() {
	const10000 := decimal.NewFromInt(10000)
	const40000 := decimal.NewFromInt(40000)
	const1000 := decimal.NewFromInt(1000)
	const7000 := decimal.NewFromInt(7000)
	rate10 := decimal.NewFromInt(10).Shift(-2)
	rate20 := decimal.NewFromInt(20).Shift(-2)
	rate30 := decimal.NewFromInt(30).Shift(-2)

	if taxRec.TrIncome.Cmp(const10000) <= 0 {
		raw := taxRec.TrIncome.Mul(rate10)
		WsTax = storeRounded(raw, 7, 2)
	} else {
		if taxRec.TrIncome.Cmp(const40000) <= 0 {
			diff := taxRec.TrIncome.Sub(const10000)
			raw := const1000.Add(diff.Mul(rate20))
			WsTax = storeRounded(raw, 7, 2)
		} else {
			diff := taxRec.TrIncome.Sub(const40000)
			raw := const7000.Add(diff.Mul(rate30))
			WsTax = storeRounded(raw, 7, 2)
		}
	}
	rawNet := taxRec.TrIncome.Sub(WsTax)
	WsNet = storeTruncated(rawNet, 7, 2)
	rawTotal := WsTotalTax.Add(WsTax)
	WsTotalTax = storeTruncated(rawTotal, 9, 2)
	WsCount = WsCount + 1
	if WsCount >= 1000 || WsCount < 0 {
		WsCount = WsCount % 1000
		if WsCount < 0 {
			WsCount += 1000
		}
	}
	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Fprintf(os.Stdout, "%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	readPara()
}

func mainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	reader = bufio.NewReader(taxFile)
	WsEofFlag = "N"
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	taxFile.Close()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	cntStr := fmt.Sprintf("%03d", WsCount)
	fmt.Fprintf(os.Stdout, "TAXPAYERS: %s TOTAL TAX: %s\n", cntStr, WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	mainPara()
}
